registerRefData('nsw-cond-n-5493',{"id":5493,"pan":null,"ref":"16-2019-445-1","address":"795 Medowie Road Medowie 2318","description":"Commercial premises (multiple-tenancies), medical centre, retail premises (pharmacy), childcare centre (126 place), site works, civil works, signage, landscaping and four lot torrens title subdivision of proposed Lot 4 (on proposed Lots 2, 3 and 4 under DA 16-2018-879-1)","outcome":"approved","outcome_raw":"Approved","outcome_source":"planning_panels","determined":null,"notice_url":"https://apps.planningportal.nsw.gov.au/prweb/PRRestService/DocMgmt/v1/PublicDocuments/DATA-WORKATTACH-FILE PEC-DPE-EP-WORK PPSHCC-4!20200522T022400.355 GMT","sha256":"157d38972d56fe69284e8986c54b37dc3985c4ae691ab190bb653c9b9b768b66","pages":22,"layout":"numbered","n":10,"fetched_at":"2026-08-17T01:20:28+00:00","file":"n/5493.js","source_page":"https://www.planningportal.nsw.gov.au/planning-panel/commercial-premises-multiple-tenancies-medical-centre-retail-premises-pharmacy","lga":"PORT STEPHENS","conditions":[{"label":"1","code":null,"number":"1","title":"","text":"PANEL REF - LGA - DA NO. PPSHCC-4 - Port Stephens Council - DA 16-2019-445","stage":"general","stage_basis":"heading","page":3},{"label":"2","code":null,"number":"2","title":"PROPOSED DEVELOPMENT Commercial premises (multiple tenancies), medical centre, retail","text":"premises (pharmacy), Centre-based childcare facility (126 place), site\nworks, civil works, signage, landscaping and one into four lot Torrens\ntitle subdivision","stage":"general","stage_basis":"heading","page":3},{"label":"3","code":null,"number":"3","title":"STREET ADDRESS 795 Medowie Road, Medowie","text":"","stage":"general","stage_basis":"heading","page":3},{"label":"4","code":null,"number":"4","title":"APPLICANT","text":"OWNER\nMedowie Retail Unit Trust\nPort Stephens Council","stage":"general","stage_basis":"heading","page":3},{"label":"5","code":null,"number":"5","title":"TYPE OF REGIONAL","text":"DEVELOPMENT Council related development over $5 million","stage":"general","stage_basis":"heading","page":3},{"label":"6","code":null,"number":"6","title":"RELEVANT MANDATORY","text":"CONSIDERATIONS\n Environmental planning instruments:\no State Environmental Planning Policy No 55 - Remediation of\nLand\no State Environmental Planning Policy (State and Regional\nDevelopment) 2011\no State Environmental Planning Policy No 44 - Koala Habitat\nProtection\no State Environmental Planning Policy (Educational\nEstablishment and Child Care Facilities) 2017\no State Environmental Planning Policy No 64 - Advertising and\nSignage\no State Environmental Planning Policy (Vegetation in Non-\nRural Areas) 2017\no Port Stephens Local Environmental Plan 2013\n Draft environmental planning instruments: Nil\n Development control plans:\no Port Stephens Development Control Plan 2013\n Planning agreements: Nil\n Provisions of the Environmental Planning and Assessment\nRegulation 2000\n Coastal zone management plan: Nil\n The likely impacts of the development, including environmental\nimpacts on the natural and built environment and social and\neconomic impacts in the locality\n The suitability of the site for the development\n Any submissions made in accordance with the Environmental\nPlanning and Assessment Act 1979 or regulations\n The public interest, including the principles of ecologically\nsustainable development","stage":"general","stage_basis":"heading","page":3},{"label":"7","code":null,"number":"7","title":"MATERIAL CONSIDERED","text":"BY THE PANEL\n Council assessment report: 4 March 2020\n Written submissions during public exhibition: nil\n Verbal submissions at the public meeting on 18 March 2020:\no Council assessment officer - Dylan Mitchell and Rean\nLourens\no On behalf of the applicant - Peter Childs, Chris Speek, Steve\nO’Connor\n Addendum Council assessment report: 24 April 2020\n Amended drawings dated 12 May 2020: DA-1103, issue 16; DA-\n1106, issue 16","stage":"general","stage_basis":"heading","page":3},{"label":"8","code":null,"number":"8","title":"MEETINGS, BRIEFINGS","text":"AND SITE INSPECTIONS BY\nTHE PANEL\n Briefing: 25 September 2019\no Panel members: Stuart McDonald (Chair), Mark Grayson\nand Chris Doohan\no Council assessment staff: Ryan Palmer and Rean Lourens\n Site inspection: 18 March 2020\no Panel members: Alison McCabe (Chair), Juliet Grant and\nTim Fletcher\no Council assessment staff: Dylan Mitchell\n Final briefing to discuss council’s recommendation, 18 March\n2020, 3pm. Attendees:\no Panel members: Alison McCabe (Chair), Juliet Grant and\nTim Fletcher\no Council assessment staff: Dylan Mitchell\n Papers circulated electronically between 27 April 2020 and 14\nMay 2020.","stage":"general","stage_basis":"heading","page":4},{"label":"9","code":null,"number":"9","title":"COUNCIL","text":"RECOMMENDATION Approval","stage":"general","stage_basis":"heading","page":4},{"label":"10","code":null,"number":"10","title":"DRAFT CONDITIONS Attached to addendum council assessment report (24 April 2020)","text":"CONDITIONS OF CONSENT - AS AMENDED\nDetails of Conditions:\n1.0 - General Conditions of Consent\nThe following conditions of consent are general conditions applying to the development.\n(1) General terms of approval - The General Terms of Approval from state authorities\nmust be complied with prior to, during, and at the completion of the development.\nThe General Terms of Approval are:\n1. NSW Rural Fire Service, R ef no. D19/2675 and dated 30 August 2019.\nA copy of the General Terms of Approval is attached to this determination notice.\n(2) External agency advice - The requirements from the following agencies must be\ncomplied with prior to, during, and at the completion of the development.\nThe Requirements are:\n1. AUSGRID, reference number 2017/33/171 and dated 12 August 2019.\nA copy of the Requirements is attached to this determination notice.\n(3) Approved plans and documentation - Development must be carried out in\naccordance with the following pl ans and documentation, and all recommendations\nmade therein, except where amended by the conditions of this development consent:\nPlan reference/\ndrawing no.\nName of plan Prepared by Date\nProject no. 19007, Sheet\nDA 0003, Issue 10\nSignage\nSchedule\nCKDS\nArchitecture\n8/04/2020\nProject no. 19007, Sheet\nDA-1002, Issue 17\nSite Plan CKDS\nArchitecture\n19/04/2020\nProject no. 19007, Sheet\nDA-1003, Issue 15\nSite Elevations CKDS\nArchitecture\n19/04/2020\nProject no. 19007, Sheet\nDA-1004, Issue 01\nSite Elevations CKDS\nArchitecture\n8/04/2020\nProject no. 19007 Sheet\nDA-1005, Issue 13\nSite Sections CKDS\nArchitecture\n8/04/2020\nProject no. 19007, Sheet\nDA-1101, Issue 15\nGym/Commercial\nLower Floor Plan\nCKDS\nArchitecture\n8/04/2020\nProject no. 19007, Sheet\nDA-1102, Issue 15\nPharmacy\nGround Floor\nPlan\nCKDS\nArchitecture\n8/04/2020\nProject no. 19007, Sheet\nDA-1104-1105, Issue 15\nPharmacy\nElevations 1 and\n2 CKDS\nArchitecture\n8/04/2020\nProject no. 19007, Sheet\nDA-1106, Issue 15\nPharmacy\nSections\nCKDS\nArchitecture\n8/04/2020\nSCHEDULE 2\nProject no. 19007, Sheet\nDA-1107, Issue 10\nPharmacy\nMateriality\nCKDS\nArchitecture\n8/04/2020\nProject no. 19007, Sheet\nDA-1201, Issue 13\nChildcare Floor\nPlan\nCKDS\nArchitecture\n8/04/2020\nProject no. 19007, Sheet\nDA-1203, Issue 13\nChildcare\nElevations\nCKDS\nArchitecture\n8/04/2020\nProject no. 19007, Sheet\nDA-1204, Issue 12\nChildcare\nSections\nCKDS\nArchitecture\n8/04/2020\nProject no. 19007, Sheet\nDA-1205, Issue 08\nChildcare\nMateriality\nCKDS\nArchitecture\n6/11/2019\nProject no. 19007, Sheet\nDA-3001, Issue 13\nCommercial\nGround Floor\nPlan\nCKDS\nArchitecture\n8/04/2020\nProject no. 19007, Sheet\nDA-3004, Issue 13\nCommercial\nElevations 1\nCKDS\nArchitecture\n8/04/2020\nProject no. 19007, Sheet\nDA-3005, Issue 02\nCommercial\nElevations 2\nCKDS\nArchitecture\n6/11/2019\nProject no. 19007, Sheet\nDA-3006, Issue 11\nCommercial\nSections\nCKDS\nArchitecture\n19/04/2020\nProject no. 19007, Sheet\nDA-3007, Issue 09\nCommercial\nMateriality\nCKDS\nArchitecture\n6/11/2019\nJob Ref: 8722 Sheet 1 of\n1, Plan No 001\nProposed\nSubdivision of\nPart Lot 1\nD.P.1215257\nDe Witt\nConsulting\n19/03/2019\nProject No. 19024 -\nSheet L101, Revision G\nOverall\nLandscape Plan\nXeriscapes 20/04/2020\nProject No. 19024 -\nSheet L102, Revision E\nChildcare\nLandscape Plan\nXeriscapes 8/04/2020\nProject No. 19024 -\nSheet L201-L202,\nRevision B\nLandscape\nSections 01 and\n02 Xeriscapes 20/04/2020\nProject No. 19024 -\nSheet L203, Revision A\nLandscape\nSections 03\nXeriscapes 20/04/2020\nProject No. 19024 -\nSheet L301, Revision B\nIndicative Plant\nSchedule\nXeriscapes 8/04/2020\nProject No. 190514\nRevision G Sheet 101\nDetail Plan ADW Johnson 14/11/2019\nProject No. 190514\nRevision G Sheet 501\nSite Regrade\nPlan\nADW Johnson 14/11/2019\nProject No. 190514\nRevision G Sheet 701\nLinemarking &\nSignage Plan\nADW Johnson 14/11/2019\nDocument title Prepared by Date\nStormwater Management\nReport\nADW Johnson November\n2019\nCPTED Statement KDC Jul y 2019\nIn the event of any inconsistency between the approved plans and the conditions, the\nconditions will prevail.\n(4) Amendments to documents and plans - The development must be amended as\nfollows:\na) The approved landscape plan (Ref no. 19024 by Xeriscapes and d a t e d\n20/04/2020), is to be amended as follows:\ni. 4 Luscious® Tristaniopsis laurina 'DOW10 trees are to be inc luded as a\nstreet trees. The trees are to be a minimum pot size of 45 litr es and taller\nthan 1.2m at the time of planting.\nii. Landscape Plan layout for the childcare centre is to be con sistent with\napproved_ architectural plans.\niii. Civil engineering plans are to be amended to reflect the approved Site\nPlan prepared by CKDS Architecture, Ref No. 19007, Issue 17 and dated\n19/04/2020; Site Elevations prepared by CKDS Architecture, Ref No.\n19007, Issue 15 and dated 19/04/2020; Landscape Sections 01 and 02\nprepared by Xeriscapes, Ref No. 19024, Revision B, dated 20/04/2020;\nand Landscape Section 03 prepared by Xeriscapes, Ref No. 19024,\nRevision A, dated 20/04/2020. Retaining wall details are to be consistent\nwith these plans.\nAmended plans or documentation dem onstrating compliance must be p r o v i d e d t o\nCouncil for approval prior to the issue of a Construction Certificate.\n(5) Separate Approval for Use - A separate development application for the fit out and\nuse of each commercial tenancy that does not have a lower order use identified must\nbe provided to, and approved by e ither the Consent Authority pr ior to that use\ncommencing or under the provisions of the State Environmental P lanning Policy\n(Exempt and Complying Codes) 2008, where applicable.\n(6) Outdoor Lighting - All lighting must comply with AS 1158 ‘Lighting for Roads and\nPublic Spaces’ and AS 4282 ‘Control of Obtrusive Effects of Outdoor Lighting’.\n(7) Shoring of Adjoining Buildings - Where any excavation required for the\ndevelopment extends below the level of the base of a footing of a building, structure\nor work on adjoining land (including within a road or rail corr idor), the person having\nthe benefit of the consent must protect and support that buildi ng, structure or work\nfrom possible damage from the e xcavation, and where necessary u nderpin the\nbuilding, structure or work to prevent any such damage.\n(8) Roof Mounted Equipment - All roof mounted equipment such as air conditioning\nunits, service pipes and vents etc., required to be installed must be concealed within\nthe external walls of the development or adequately screened so as not to be visible\nfrom a public place.\n(9) Proposed Lot 1 - No approval is granted for any building, carpark or use on proposed\nLot 1 other than earthworks, retaining wall and landscape works\n.\n2.0 - Prior to Issue of a Subdivision Works Certificate\n(1) Subdivision Works Certificate Required - In accordance with the provisions of\nSection 6.13 of the Environmental Planning & Assessment Act 1979 (EP&A Act 1979),\nconstruction or subdivision works approved by this consent must not commence until\nthe following has been satisfied:\na) a Subdivision Works Certific ate has been issued by a Consent Authority;\nb) a Principal Certifying Au thority (PCA) has been appointed by the person having\nbenefit of the development consent in accordance with Section 6 .5 of the EP&A\nAct 1979; and\nc) the PCA is notified in writi ng of the name and contractor li cence number of the\nowner/builder intending to carry out the approved works.\n(2) Civil engineering Plans - Civil engineering plans prepared by a qualified Civil\nEngineer, indicating drainage, r oads, accessways, earthworks, p avement design,\nstreet lighting, details of li ne-marking, traffic management, w ater quality and quantity\nfacilities including stormwater detention and disposal, must be prepared in accordance\nwith the approved plans and Council’s Infrastructure Specifications.\nDetails demonstrating compliance must be provided to the Certifying Authority.\nNote. Under the Roads Act 1993, only the Roads Authority can ap prove\ncommencement of works within an existing road reserve.\n(3) Hunter Water Corporation Approval - A Section 49 Application under the Hunter\nWater Act 1991 must be lodged with Hunter Water Corporation (HWC) and details of\nthe Notice of Compliance from HWC must be provided to the Certifying Authority.\n(4) Stormwater/Drainage Plans - Detailed stormwater drainage plans must be prepared\nby a qualified Engineer in accordance with the approved plans, Council’s Infrastructure\nSpecifications and the current A ustralian Rainfall and Runoff g uidelines using the\nHydrologic Soil Mapping data for Port Stephens (available from Council).\nDetails demonstrating compliance must be provided to the Certifying Authority.\nNote. Under the Roads Act 1993, only the Roads Authority can ap prove\ncommencement of works within an existing road reserve.\n(5) Footings and Excavation near Council Property - All works proposed within the\nzone of influence of Council’s asset/s are to be designed and c ertified by a qualified\nGeotechnical or Structural Engineer.\nPlans and specifications demonstr ating compliance with this req uirement must be\nsubmitted to the Certifying Authority.\n(6) Dilapidation Report Council Property - A Dilapidation Report prepared by a qualified\nStructural/Civil Engineer must be submitted to the Certifying Authority.\nThe report must include a photographic survey of existing publi c roads, kerbs,\nfootpaths, drainage structures, street trees and any other existing public infrastructure\nwithin the immediate area of the subject site. The report must also include the retaining\nwall on the southern boundary adjoining Lot 1: DP: 1196650.\nAll costs incurred in achieving compliance with this condition\nmust be borne by the\napplicant.\nDetails demonstrating compliance must be provided to the Certifying Authority.\n(7) Stormwater System Operation and Maintenance Procedure Plan - An Operation\nand Maintenance Plan for the stormwater system must be prepared by a qualified\nengineer detailing a regular mai ntenance programme for pollutio n control devices,\ncovering inspection, cleaning and waste disposal.\nDetails demonstrating compliance must be provided to the Certifying Authority.\n(8) Retaining walls - All retaining walls must be designed and certified by a suit ably\nqualified Structural Engineer in accordance with Council's Infrastructure Specifications.\nDetails demonstrating compliance must be provided to the Certifying Authority.\n(9) Soil, erosion, sediment and water management - An Erosion and Sediment Control\nPlan (ESCP) must be prepared in a ccordance with Council’s Infra structure\nSpecifications. Details demonstr ating compliance must be provid ed to the Certifying\nAuthority.\n(10) Roads Act Approval - For construction/reconstruction of Council infrastructure,\nincluding vehicular crossings, footpath, kerb and gutter, storm water drainage, an\napplication must be made for a Roads Act Approval Certificate under Section 138B of\nthe Roads Act 1993. The following information must be provided to Council as the\nRoads Authority with the Roads Act application:\na) Detailed civil engineering pl ans indicating line-marking and traffic management\nfor a channelised right hand turning lane on Medowie Road and d irecting traffic\nto Muir Street.\n3.0 - Prior to Issue of a Construction Certificate\nThe following conditions of consent shall be complied with prior to the issue of a Construction\nCertificate.\n(1) Hunter Water Corporation Approval - A Section 49 Application under the Hunter\nWater Act 1991 must be lodged with Hunter Water Corporation (HWC) and details\nof the Notice of Compliance from HWC must be provided to the Certifying Authority.\n(2) Civil engineering plans - Civil engineering plans prepared by a qualified Engineer,\nindicating drainage, roads, access ways, earthworks, pavement d esign, street\nlighting, details of line-marking, traffic management, water qu ality and quantity\nfacilities including stormwater detention and disposal, must be prepared in\naccordance with the approved plans and Council’s Infrastructure Specifications.\nDetails demonstrating compliance must be provided to the Certifying Authority.\nNote. Under the Roads Act 1993 , only the Roads Authority can approve\ncommencement of works within an existing road reserve.\n(3) Stormwater/drainage plans - Detailed stormwater drainage plans must be\nprepared by a qualified Engineer in accordance with the approve d plans, Council’s\nInfrastructure Specifications and the current Australian Rainfall and Runoff guidelines\nusing the Hydrologic Soil Mapping data for Port Stephens (available from Council).\nDetails demonstrating compliance must be provided to the Certifying Authority.\nNote. Under the Roads Act 1993 , only the Roads Authority can approve\ncommencement of works within an existing road reserve.\n(4) Footings and excavation near Council property - All works proposed within the\nzone of influence of Council’s asset/s are to be designed and c\nertified by a qualified\nGeotechnical or Structural Engineer.\nPlans and specifications demonstr ating compliance with this req uirement must be\nsubmitted to the Certifying Authority.\n(5) Dilapidation Report - Council property - A Dilapidation Report prepared by a\nqualified Structural/Civil Engineer must be submitted to the Certifying Authority.\nThe report must include a photogr aphic survey of existing publi c roads, kerbs,\nfootpaths, drainage structures, s treet trees and any other exis ting public\ninfrastructure within the immedi ate area of the subject site. The report must also\ninclude the retaining wall on the southern boundary adjoining Lot 1: DP: 1196650.\nAll costs incurred in achieving compliance with this condition must be borne by the\napplicant.\nDetails demonstrating compliance must be provided to the Certifying Authority.\n(6) Stormwater system Operation and Maintenance Procedure Plan - An Operation\nand Maintenance Plan for the stormw ater system must be prepared by a qualified\nengineer detailing a regular mai ntenance programme for pollutio n control devices,\ncovering inspection, cleaning and waste disposal.\nDetails demonstrating compliance must be provided to the Certifying Authority.\n(7) Retaining walls - All retaining walls must be designed and certified by a suit ably\nqualified Structural Engineer in accordance with Council's Infr astructure\nSpecifications.\nDetails demonstrating compliance must be provided to the Certifying Authority.\n(8) Soil, erosion, sediment and water management - An Erosion and Sediment\nControl Plan (ESCP) must be prepared in accordance with Council ’s Infrastructure\nSpecifications. Details demonstrating compliance must be provided to the Certifying\nAuthority.\n(9) Roads Act Approval - For construction/reconstruc tion of Council infrastructure,\nincluding vehicular crossings, footpath, kerb and gutter, storm water drainage, an\napplication must be made for a Roads Act Approval Certificate u nder Section 138B\nof the Roads Act 1993. The following information must be provided to Council as the\nRoads Authority with the Roads Act application:\na) Detailed civil engineering pl ans indicating line-marking and traffic management\nfor a channelised right hand turning lane on Medowie Road and d irecting traffic\nto Muir Street.\n(10) Construction Environmental Management Plan - A Construction Environmental\nManagement Plan (CEMP) is to be submitted to and approved by th e Certifying\nAuthority. The required CEMP m ust outline the sequence and cons truction\nmethodology and specify mitigating measures to ensure all works are carried out with\nminimal environmental impact in r elation to project staging, wa ste management,\nnoise and dust management, traffic management and environmental management\n(11) Section 7.12 devel opment contributions - A monetary contribution is to be paid to\nCouncil, pursuant to Section 7.12 of the Environmental Planning & Assessment Act\n1979 and the Port Stephens Council Fixe d Local Infrastructure Contr ibutions Plan,\nrelated to the Capital Investment Value (CIV) of the developmen t as determined in\naccordance with clause 25j of the Environmental Planning and Assessment\nRegulation 2000 and outlined in the table below.\nCapital Investment Value Levy Rate (% of CIV)\nUp to and including $100,000 Nil\nMore than $100,000 and up to and\nincludin\ng $200,000\n0.5%\nMore than $200,000 1%\nThe payment of the fixed development consent levy is to be accompanied by a Cost\nSummary Report Form setting out an estimate of the CIV in accor dance with\nSchedule 1 of the Port Stephens Council Fixed Development Contributions Plan.\nWhere the estimated cost of carrying out the whole of the development is more than\n$1,000,000, the Cost Summary Repor t Form must be completed by a Quantity\nSurveyor who is a Registered Associate member or above, of the Australian Institute\nof Quantity Surveyors.\nThis condition cannot be taken to be satisfied until a payment has been made in\naccordance with the CIV stated on a cost summary report submitt ed to Council in\naccordance with this condition.\nPayment of the above amount must apply to Development Applications as follows:\na) Building work only - prior to the issue of the Construction Certificate.\n(12) Long service levy - In accordance with Section 34 of the Building and Construction\nIndustry Long Service Payments Act 1986, the applicant must pay a long service levy\nat the prescribed rate to either the Long Service Payments Corporation or Council for\nany works that cost $25,000 or more.\n(13) Food Premises Fit Out - A detailed floor plan of the child care facility kitchen fit out\nthat demonstrates compliance with AS4674-2004 a nd the Australia New Zealand\nFood Standards code is to be submitted to Council for approval.\nThis plan will need to clearly identify all relevant fixtures and fittings (including but not\nlimited to, the designated hand wash basins, and cleaning/utility sinks).\nIf mechanical ventilation is required, the installation and fit-out must comply with AS\n1668.2-2012 (as amended from time to time), the building code of Australia, and any\nother relevant standard or legislative instrument.\n(14) Public Toilets - Plans are to be submitted to the certifying authority, detai ling the\nprovision of at least one unisex toilet facility made accessible to the public to cater for\neach commercial tenancy.\n( 1 5 ) P u b l i c A r t - Public Art Approval is to be obtained from Council for the area s\ndesignated on the approved site plan (Project no. 19007 Revisio n 17 and dated\n19/04/2020). Public Art is to be in accordance with Councils Pu blic Art Policy and\nGuidelines for the approval and installation of public art in Port Stephens.\n4.0 - Prior to Commencement of Works\nThe following conditions of consent shall be complied with prio r to any works commencing\non the development site.\n(1) Public liability insurance - The owner or contractor must take out a Public Liability\nInsurance Policy with a minimum cover of $20 million in relation to the occupation of,\nand works within, public property (i.e. kerbs, gutters, footpaths, walkways, reserves,\netc.) for the full duration of the proposed works.\nEvidence of this Policy must be provided to Council and the Certifying Authority.\n(2) Notice of Principal Certify ing Authority appointment - Notice must be given to\nCouncil at least two days prior to subdivision and/or building works commencing in\naccordance with Clause 103 of the Environmental Planning & Assessment Regulation\n2000. The notice must include:\na) a description of the work to be carried out;\nb) the address of the l and on which the work is to be carried out;\nc) the Registered number and date of issue of the relevant development consent;\nd) the name and address of the Prin cipal Certifying Authority ( PCA), and of the\nperson by whom the PCA was appointed;\ne) if the PCA is an accredited certifier, their accreditation n umber, and a statement\nsigned by the accredited certifier consenting to being appointed as PCA; and\nf) a telephone number on which the PCA may be contacted for business\npurposes.\n(3) Notice commencement of work - Notice must be given to Council at least two days\nprior to subdivision and/or building works commencing in accordance with Clause 104\nof the Environmental Planning & A ssessment Regulation 2000 . The notice must\ninclude:\na) the name and address of the person by whom the notice is being given;\nb) a description of the work to be carried out;\nc) the address of the l and on which the work is to be carried out;\nd) the Registered number and date of issue of the relevant deve lopment consent\nand construction certificate;\ne) a statement signed by or on behalf of the Principal Certifyi ng Authority to the\neffect that all conditions of t he consent that are required to be satisfied prior to\nthe work commencing have been satisfied; and\nf) the date on which the work is intended to commence.\n(4) Sign of PCA and contact details - A sign must be erected in a prominent position on\nthe site stating the following:\na) that unauthorised entry to the work site is prohibited;\nb) the name of the principal cont ractor (or person in charge of the site) and a\ntelephone number on which that person can be contacted at any time for business\npurposes and outside working hours;\nc) the name, address and telephon e number of the Principal Certifying Authority.\nThe sign must be maintained while the work is being carried out and must be removed\nupon the completion of works.\n(5) Construction Certificate Required - In accordance with the provisions of Section 6.7\nof the Environmental Planning & Assessment Act 1979 (EP&A Act 1979), construction\nor subdivision works approved by this consent must not commence until the following\nhas been satisfied:\na) a Construction Certificate has been issued by a Consent Authority;\nb) a Principal Certifying Au thority (PCA) has been appointed by the person having\nbenefit of the development consent in accordance with Section 6.5 of the EP&A\nAct 1979; and\nc) the PCA is notified in writing of the name and contractor li cence number of the\nowner/builder intending to carry out the approved works.\n(6) Site is to be secured - The site must be secured and fenced to the satisfaction of the\nPrincipal Certifying Authority. All hoarding, fencing or awning s (associated with\nsecuring the site during construction) is to be removed upon the completion of works.\nAn awning is to be erected that would sufficiently prevent any substance from the\nconstruction work falling onto public property. The work site m ust be kept lit between\nsunset and sunrise if it is likely to be hazardous to persons on public property.\n(7) Soil erosion and sediment control - Soil erosion and sedime nt controls must be\nimplemented prior to works commencing on the site in accordance with ‘Managing\nUrban Stormwater - Soils and Construction ('the blue book') and any Sediment and\nErosion plans approved with this Development Consent.\nSoil erosion and sediment control measures must be maintained d uring construction\nworks and must only be removed upon completion of the project when all landscaping\nand disturbed surfaces have been stabilised (for example, with site turfing, paving or\nre-vegetation).\n(8) All weather access - A 3m wide all-weather vehicle access is to be provided from the\nkerb and gutter to the building under construction for the delivery of materials and use\nby trades people.\nNo materials, waste or the like are to be stored on the all-weather access at any time.\n(9) Rubbish generated from the development - Where not already available, a waste\ncontainment facility is to be established on site. The facility is to be regularly emptied\nand maintained for the duration of works.\nNo rubbish must be stockpiled in a manner which facilitates the rubbish to be blown or\nwashed off site. The site must be cleared of all building refus e and spoil immediately\nupon completion of the development.\n(10) Weed management - Weed removal and suppression must be undertaken using\napproved bush regeneration techniques under the supervision of a suitably qualified\nand approved bush regenerator and in accordance with the requirements for the NSW\nBiosecurity Act 2015, associated Regulations and NSW Weed Control Handbook.\nThe site is to be inspected by a representative of Council’s Invasive Species team one\nweek prior to works commencing.\n5.0 - During Works\nThe following conditions of consent shall be complied with during the construction phase of\nthe development.\n(1) BCA Compliance - All building work must be carried out in accordance with the BCA.\nIn this clause, a reference to the BCA is a reference to that C ode as in force on the\ndate the application for the relevant Construction Certificate\nis made.\n(2) Construction hours - All work (including delivery of materials) must be restricted to\nthe hours of 7.00am to 5.00pm Monday to Saturday inclusive. Wor k is not to be\ncarried out on Sundays or Public Holidays.\n(3) Toilet facilities - Temporary toilet(s) must be provided and maintained on site from\nthe time of commencement of building work to completion. The nu mber of toilets\nprovided must be one toilet per 20 persons or part thereof empl oyed on the site at\nany one time.\nThe temporary toilet is to be either connected to the sewerage system or an approved\nseptic tank or otherwise may be a chemical toilet supplied by a licensed contractor.\n(4) Excavations and backfilling - All excavations and backfilling associated with this\ndevelopment consent must be executed safely, and be properly guarded and protected\nto prevent them from being dangerous to life or property, and i n accordance with the\ndesign of a suitably qualified Structural Engineer.\nIf an excavation extends below the level of the base of the footings of a building on an\nadjoining allotment, the person causing the excavation must:\na) preserve and protect the building from damage; and\nb) if necessary, underpin and suppo rt the building in an approved manner; and\nc) give at least seven days not ice to the adjoining owner befor e excavating, of the\nintention to excavate.\nThe principal contractor, owner builder or any person who needs to excavate and\nundertake building work, must cont act “Dial Before You Dig” pri or to works\ncommencing, and allow a reasonable period of time for the utilities to provide locations\nof their underground assets.\nThis condition does not apply if the person having the benefit of the development\nconsent owns the adjoining land or the owner of the adjoining land has given consent\nin writing to that condition not applying.\n(5) Stormwater disposal - Following the installation of any roof, collected stormwater\nrunoff from the structure must be:\na) Connected to the approved stor mwater drainage easement/system/street.\n(6) Placement of fill - Filling must not be placed in such a manner that natural dra inage\nfrom adjoining land will be obstructed or in such a manner that surface water will be\ndiverted.\nFurther, any alterations to the natural surface contours must n ot impede or divert\nnatural surface water runoff so as to cause a nuisance to adjoining property owners.\n(7) Disposal of stormwater - Water seeping into any site excavations is not to be\npumped into the stormwater system unless it complies with relev ant Environmental\nProtection Agency and Australia n and New Zealand Environment an d Conservation\nCouncil standards for water quality discharge.\n(8) Weed management - All machinery that has operat ed in affected areas shall be\ncleaned thoroughly prior to leavi ng the site. A wash down area shall be established,\nand subsequently monitored for the presence of Biosecurity Matt er ‘Alligator Weed’.\nCleaning must include the removal of all mud and plant matter, followed by washing\nwith high pressure water.\nAn area for storage of contaminat ed soil that is separate from clean material shall be\nprovided during construction.\n(9) Unexpected finds contingency (general) - Should any suspect materials (identified\nby unusual staining, odour, discolouration or inclusions such a s building rubble,\nasbestos, ash material, etc.) be encountered during any stage o f works (including\nearthworks, site prep aration or construction works, etc.), such works must cease\nimmediately until a qualified environmental specialist has be contacted and conducted\na thorough assessment.\nIn the event that contamination is identified as a result of th is assessment and if\nremediation is required, all work s must cease in the vicinity o f the contamination and\nCouncil must be notified immediately.\nWhere remediation work is required, the applicant will be requi red to obtain consent\nfor the remediation works.\n(10) Soil, erosion, sediment and water management - All requirements of the Erosion\nand Sediment Control Plan or So il and Water Management Plan mus t be maintained\nat all times during the works and any measures required by the plan must not be\nremoved until the site has been stabilised.\n(11) Offensive noise, dust, odour and vibration - All work must not give rise to offensive\nnoise, dust, odour or vibration as defined in the Protection of the Environment\nOperations Act 1997 when measured at the nearest property boundary.\n(12) Delivery register - The applicant must maintain a register of fill deliveries wh ich\nincludes date, time, truck registration number, quantity of fill, origin of fill and type of fill\ndelivered.\nThis register must be made available to Council officers on request and be provided to\nthe Council at the completion of the development.\n(13) Fill material - The only fill material that may be received at the development site is:\na) Virgin excavated natural mat erial (VENM) within the meaning of the Protection of\nthe Environment Operations Act (POEO Act 1997); or\nb) Excavated natural material (ENM) within the meaning of the POEO Act 1997; or\nc) Any other waste-derived material the subject of a resource r ecovery exemption\nunder s.91 of the Protection of the Environment Operations (Waste) Regulation\n2014 that is permitted to be used as fill material.\nAny waste-derived fill material the subject of a resource recovery exemption received\nat the development site must be accompanied by documentation as to the material's\ncompliance with the exemption conditions and must be provided t o the Principal\nCertifying Authority.\nAny fill, soil, mulch and plant brought onto the site must be c ertified as free of weeds\nand weed seeds.\n(14) Construction Environmental Management Plan - All operations must be carried\nout in accordance with the reco mmendations contained in the Con struction\nEnvironmental Management including:\na) Noise mitigation measures.\nb) Traffic management.\nc) Noise and/or vibration monitoring.\nd) Use of respite periods.\ne) Complaints handling.\nf) Community liaison and consultation.\n(15) Construction Noise Mitigation - Construction of the development must comply with\nthe recommendations of the Acoustic Assessment Report No. MAC19 0867RP1V1,\nprepared by Muller Acoustic Consulting Pty Ltd and dated 9 July 2019.\n(16) Survey Report - The buildings must be set out by a Registered land surveyor. A peg\nout survey detailing the siting of the building in accordance w ith the approved plans\nmust be provided to the Principal Certifying Authority prior to the pouring of concrete.\n(17) Potential acid sulfate soils - Should ASS be encountered within the zone of works,\nan ASS Management Plan is to be prepared by a suitably qualifie d Geotechnical\nEngineer and submitted to the Certifying Authority.\nThe recommendations and/or mitigat ion measures contained within the ASS\nManagement Plan must be complied with during works.\n6.0 - Prior to Issue of a Subdivision Certificate\nThe following conditions of consent shall be complied with prior to the issue of a Subdivision\nCertificate.\n(1) Requirement for a Subdivision Certificate - The application for Subdivision\nCertificate(s) must be made in accordance with the requirements of Clause 157 of the\nEnvironmental Planning & Assessment Regulations 2000.\nThe applicant will be required to s ubmit documentary evidence t hat the property has\nbeen developed in accordance with the plans approved by this de velopment consent\nDA 16-2019-445-1, and of compliance with the relevant conditions of consent, prior to\nthe issuing of a Torrens Title Plan of Subdivision.\nIn addition, one signed original copy of the original plans and /or documents, and final\nplan of survey/title, must be submitted to Council. A USB containing an electronic copy\nof all relevant documents must also be provided.\n(2) Show easements / restricti ons on the Plan of Subdivision - The developer must\nacknowledge all existing easemen ts and/or restrictions on the u se of the land on the\nfinal plan of subdivision.\n(3) Burdened lots to be identified - Any lots subsequently identified during construction\nof the subdivision as requiring restrictions must also be suitably burdened.\n(4) Subdivision Certificate - The issue of a Subdivision Certificate is not to occur until\nall conditions of this development consent have been satisfacto rily addressed and all\nengineering works are complete.\nWorks As Executed Plans must be prepared and provided to the Pr incipal Certifying\nAuthority in accordance with Council's Infrastructure Specifica tions and approved\nplans.\n(5) Surveyor’s Report - A certificate from a Registered Surveyor must be provided to the\nPrincipal Certifying Authority, certifying that all drainage li nes have been laid within\ntheir proposed easements.\nCertification is also to be prov ided stating that no services o r accessways encroach\nover the proposed boundary other than as provided for by easeme nts as created by\nthe final plan of subdivision.\n(6) Street lighting - Street lighting must be provided within the subdivision in accordance\nwith the relevant Australian Standards and to the satisfaction of the Principal Certifying\nAuthority. All such work must be complete and operative.\n(7) Services - Evidence is to be provided to Council demonstrating that the following\nreticulated services are available to each lot:\na) Electricity.\nb) Water.\nc) Sewer.\nShould any of the above reticulated services not be available to the development site,\na detailed statement is to be provided explaining why connection of the relevant service\nis not possible or practical.\n(8) Section 88B Instrument - The applicant must prepare a Section 88B Instrument\nwhich incorporates the followi ng easements, positive covenants and restrictions to\nuser where necessary:\na) easement for services;\nb) easement to drain water and drainage easement/s over overland flow paths;\nc) easement for on-site detention;\nd) positive covenant over the on- site detention / water quality facility for the\nmaintenance, repair and insurance of such a facility;\ne) retaining wall, positive cov enant, and restriction to user; and\nf) reciprocal right of carriageway over internal driveways be nefitting all lots (the\nowners of the subject properties burdened by the right of carri ageway must be\nresponsible for ongoing maintenanc e and the Public Liability of the right of\ncarriageway).\n(9) Stormwater management facility - A stormwater management facility must be\nconstructed for the site in a ccordance with the approved plans and Council’s\nInfrastructure Specification.\n(10) Stormwater Management Fac ility Operation, Maintenance and Monitoring\nManual/s - Operation, Maintenance and Moni toring Manual/s ('Manuals') for the\nstormwater management facility must be provided for approval to the Principal\nCertifying Authority. The Manual(s) must be prepared by a qualified Engineer.\n(11) Subdivision Registration - The Subdivision Certificate for DA 16-2018-789-1 must\nbe registered with Land Registry Ser vices. Proof of registratio n of the land must be\nprovided to the Principle Certifying Authority.\n7.0 - Prior to Issue of an Occupation Certificate\nThe following conditions of consent shall be complied with prior to the issue of an Occupation\nCertificate.\n(1) Occupation Certificate Required - An Occupation Certificate must be obtained prior\nto any use or occupation of the development.\nThe Principal Certifying Authorit y must be satisfied that the d evelopment has been\nconstructed in accordance with approved plans, specifications a nd conditions of this\nconsent.\n(2) Rectification damage to public infrastructure - The applicant must rectify any new\ndamage to public infrastructure to the satisfaction of the Coun cil as the Roads\nAuthority.\n(3) Completion of Roads Act Approval works - All approved road, footpath and/or\ndrainage works, including vehicle crossings, have been completed in the road reserve\nin accordance with the Roads Act Approval to the satisfaction o f the Council as the\nRoads Authority.\n(4) Works as Executed Plans and Report - Works As Executed Plans must be prepared\nand provided to the Principal Cer tifying Authority in accordanc e with Council's\nInfrastructure Specifications c onfirming all stormwater drainag e systems are\nconstructed in accordance with the approved plans/documentation.\n(5) Geotechnical Compliance Certificate - A Certificate of Comp liance prepared by a\nqualified Geotechnical Engineer must be provided to the Principal Certifying Authority\nstating that the works detailed in the Geotechnical Report have been undertaken under\nthe Engineer’s supervision and to the Engineer’s satisfaction, and that the assumptions\nrelating to site conditions made in preparation of the report w ere validated during\nconstruction.\nThis certificate must accompany the Works as Executed plans.\n(6) Completion of landscape works - All landscape works are to be undertaken in\naccordance with the approved l andscape plan as amended by condi tion 2 (4) of this\nconsent and conditions of this Development Consent.\n(7) Acoustic Fencing - A 2m acoustic fence is to be constructed along the southern and\neastern boundary of the childcare facility.\n(8) Construction to be in accordance with Acoustic Report - Certification is to be\nsubmitted to the Principal Certifying Authority to certify that the construction of the\ndevelopment complies with the recommendations of the Acoustic Assessment Report\nNo. MAC190867RP1V1, prepared by Mul ler Acoustic Consulting Pty Ltd and dated\n9 July 2019.\n(9) Bushfire safety - The site is located within a bushfire prone area. Certification from\na suitably qualified Bushfire Consultant must be provided to certify that the\nconstruction of the development complies with:\na) The NSW RFS’ General Terms o f Approval - Ref no. D19/2675 and dated 30\nAugust 2019;\nb) The Bushfire Report provided wi th the DA titled Bushfire Assessment Report, by\nNewcastle Bushfire Consulting and dated 04/07/2019; and\nc) The NSW Rural Fire Service publication \"Planning for Bush Fire Protection 2006.\"\n(10) Fire Safety Certificates - A Fire Safety Certificate must be provided to the PCA in\naccordance with the requirements of the Environmental Planning & Assessment\nRegulation 2000.\n(11) Survey Certificate - A Registered Surveyor must prepare a Survey Certificate to\ncertify that the location of the building in relation to the allotment boundaries complies\nwith the approved plans or as specified by this consent. The Survey Certificate must\nbe provided to the satisfaction of the Principal Certifying Authority.\n(12) Public Art - Public art is to be installed in accordance with the Public Art Approval\nnoted in Condition 3(15) of this consent.\n(13) Emergency Evacuation - An emergency evacuation plan for the childcare facility is\nto be prepared in accordance with the Education and Care Servic es National\nRegulations and the latest versi on of the Child Care Planning G uideline (NSW\nDepartment of Planning & Environment ) and provided to the satis faction of the\nPrincipal Certifying Authority.\n(14) Footpath Crossing Construction - A footpath crossing and driveway must be\nconstructed in accordance with th is consent and the approved Co nstruction\nCertificate prior to use or occupation of the development.\nNote: A Works on Public Infrastructure (Driveway) approval must be obtained prior to\nthe commencement of such works.\n(15) Directional Traffic Flow Signs- All driveways must be suitably signposted and\ndirectional arrows painted on the internal driveways. All signs must be maintained in\ngood repair at all times.\n(16) Food Premises - Council must be notified that the premises is being used for the\npreparation, manufacture or storage of food for sale and an inspection of the\ncompleted fit out is to be conducted.\nA 'Food Business Registration form can be found on Council’s website.\n(17) Subdivision Registration - The Subdivision Certificate for DA 16-2018-789-1 must\nbe registered with Land Registry Services. Proof of registration of the land must be\nprovided to the Principle Certifying Authority.\n(18) Goods Lift - The goods lift identified on the architectural plans prepared by CKDS\nArchitecture, project no.19007 and dated 19/04/2020, must be installed to enable\nthe ground level commercial tenancies fronting Peppertree Road\naccess to the\nwaste enclosure and loading area at the rear of the building.\nThe goods lift must be maintai ned in working order at all times.\n(19) Child Care Facility Operation Approval - Prior to the occupation of use of the child\ncare facility, the applicant must obtain a Service Approval for the operation of a child\ncare facility from the Regulatory Authority.\n(20) ANS09 - Plan of Management - A Plan of Management for the operation of the child\ncare centre is to be provided to Council for approval prior to issue of any Occupation\nCertificate. The ongoing operation of the centre must be in accordance with the plan,\ntaking into consideration any recommendations made by a suitabl y qualified and\nexperienced acoustic consultant. The Plan of Management must in clude, but is not\nlimited to the following:\n Mitigating measures to minimi se amenity impacts on surrounding residential\nproperties\n Mitigating measures to minimise acoustic amenity impacts on oc cupants of the\nfacility\n Managing noise impacts emanat ing from the premises.\n Identifying measures to minimise potential noise impacts from outdoor play areas\nand specifically:\n the number of children and t heir age groups in each area.\n the type of play those childr en will engage in in those areas.\n the hours of play for thos e children in those areas.\n Deliveries and waste collection services.\n Management of carpark operations including drop off and pick u p and the\ndesignation of areas.\n8.0 - Ongoing Use\nThe following conditions of consent are operational conditions applying to the development.\n(1) Hours of Operation- The property is only to be open for business and used for the\npurpose approved within the following hours:\nApproved Hours of Operation\nDay Pharmacy Medical All\nCommercial\ntenancies\nChildcare\nFacility\nMon -Fri 8am - 7pm 8am - 7pm 8am - 6pm 6am - 7pm\nSat 8am - 5pm 8am - 7pm 9am - 5pm No operation\nSun / Public\nHols\n8am - 5pm 8am - 5pm 9am - 5pm No operation\nOther internal operations such as cleaning, preparation, and of fice administration may be\nundertaken outside of the above hours provided no disturbance t o the amenity of the\nneighborhood occurs\n.\n(2) Childcare Facility Occupancy - The childcare centre is approved for a maximum\ncapacity of 126 child care places. Any increase in this number shall be subject to\nseparate approval from Council.\n(3) Maintenance of Acoustic Fence - The acoustic fence must be maintained throughout\nthe life of the development.\n(4) Fire Safety Schedule - At all times, a copy of the Fire Safety Schedule and Fire Safety\nCertificate must be prominently displayed in the building and a copy forwarded to the\nCommissioner of New South Wales Fire Brigades in accordance wit h the\nEnvironmental Planning & Assessment Regulations 2000.\n(5) Illuminated Signage - The approved signs must be maintained in a presentable and\nsatisfactory state of repair.\nThe level of illumination and/or lighting intensity used to ill uminate the sign/s must\ncomply with AS 1158 ‘Lighting for Roads and Public Spaces’ and AS 4282 ‘Control of\nObtrusive Effects of Outdoor Lighting’.\n(6) Bird strike - As the subject site is located in an area mapped by the Departm ent of\nDefence as “Birdstrike Group B” , organic waste and/or the stora ge of bins associated\nwith any future development must be covered and/or enclosed and limited on-site.\n(7) Waste Disposal - The building owner must ensure th at there is a contract with a\nlicensed contractor for the removal of all waste. No garbage is to be placed on public\nland (e.g. footpaths, roadways, plazas, reserves) at any time. Waste storage areas are\nto be suitably screened at all times.\n(8) Parking - Signage (Loading docks) - Proposed parking areas, service bays, truck\ndocks, driveways and turning areas must be maintained clear of obstructions and be\nused exclusively for purposes of car parking, loading/ unloadin g, and vehicle access\nrespectively for the life of the development. Under no circumstances are such areas to\nbe used for the storage of goods or waste materials.\n(9) Driveways to be Maintained - All access crossings and driveways must be maintained\nin good order for the life of the development.\n(10) Removal of Graffiti - The owner/manager of the site is responsible for the removal o f\nall graffiti from the building and fences within 48 hours of its application.\n(11) Maintenance of Landscaping - Landscaping must be maintained in accordance with\nthe approved landscape plan and conditions of this development consent. All landscape\nareas must be kept free of parked vehicles, stored goods, garbage or waste material at\nall times.\nIf any of the vegetation dies or is removed, it is to be replaced with vegetation of the\nsame species and similar maturity as the vegetation which has died or was removed.\nAdvice Notes:\n(1) 'Dial Before you Dig' - Before any excavation work starts, contractors and others\nshould phone the “Dial Before You Dig” service to access plans/ information for\nunderground pipes and cables.\n(2) Dividing fences - The erection of dividing fences under this consent does not affect\nthe provisions of the Dividing Fences Act 1991 . Under this Act, all relevant parties\nmust be in agreement prior to the erection of any approved divi ding fence/s under\nthis consent.\nCouncil has no regulatory authority in this area and does not adjudicate civil disputes\nrelating to the provision of, or payment for, the erection of d ividing fences. If there is\na neighbour dispute about the b oundary fence and you are seekin g mediation, you\nmay contact the Community Justice Centre, or if legal advice or action is required,\nyou may contact the Chamber Magistrate.\n(3) Aboriginal archaeological deposit - In the event of any Aboriginal artefact, object\nor structure being unearthed, all work must cease immediately i n the affected area,\nand the Biodiversity Conservation Division (BCD) shall be informed of the discovery.\nWork must not recommence until t he material has been inspected and permission\nhas been given by BCD to proceed.\n(4) Works near/adjoining el ectricity network assets - There are underground\nelectricity network assets adjac ent to the proposed development . Any works\nundertaken adjacent to Ausgrid underground assets must be undertaken with care in\naccordance with Ausgrid Network Standard Document NS 156 - Work Near or\nAround Underground Cables.\n(5) Council must be nominated as PCA for subdivision works - Under Section 6.5\nof the Environmental Planning & Assessment Act 1979 , Council shall be nominated\nas the Principal Certifying Aut hority for subdivision work and has the option of\nundertaking inspection of physical construction works.\n(6) Component certificates (where Council is PCA) - Where Council is appointed as\nthe Principal Certifying Authorit y for the development, the fol lowing component\ncertificates, as relevant to t he development, shall be provided prior to the issued of a\nfinal Occupation Certificate:\na) Insulation installation certificates.\nb) Termite management system i nstallation certificates.\nc) Smoke alarm installation cert ificate from installing licensed electrician.\nd) Survey certificate(s), prepar ed by a registered land surveyor, certifying that the\nbuilding has been correctly and wholly located upon the subject allotment.\ne) Certification attesting that retaining walls have been const ructed in accordance\nwith Engineers details or manufacturers specifications as applicable.\nf) All certificates or information relating to BASIX complian c e f o r t h e\ndevelopment.\ng) A certificate certifying that the wet areas have been waterp roofed in accordance\nwith the requirements of the Building Code of Australia.\nh) All certificates relating to salinity, as required by conditions of the Development\nConsent.\ni) Any other certificates relating to the development (for ex ample, engineering\ncertification for foundations, piers, reinforcing steel or hydr aulic certification for\nall stormwater drainage works).\nWhere the appointed PCA is not C ouncil, the matters listed in t his condition should be\nregarded as advisory only.\nNote: The above certification does not override any requirements of the Environmental\nPlanning & Assessment Act 1979\nwith respect to any required critical stage inspections.","stage":"general","stage_basis":"heading","page":4}]});
